import sys, types, importlib, numbers, warnings
from abc import ABCMeta
from inspect import signature

# Manually test _build_repr logic
def _pprint(params, offset=0, printer=repr):
    params_list = list()
    this_line_length = offset
    line_sep = ',\n' + (1 + offset) * ' '
    for i, (k, v) in enumerate(sorted(params.items())):
        if type(v) is float:
            this_repr = '%s=%s' % (k, str(v))
        else:
            this_repr = '%s=%s' % (k, printer(v))
        if len(this_repr) > 500:
            this_repr = this_repr[:300] + '...' + this_repr[-100:]
        if i > 0:
            if (this_line_length + len(this_repr) >= 75 or '\n' in this_repr):
                params_list.append(line_sep)
                this_line_length = len(line_sep)
            else:
                params_list.append(', ')
                this_line_length += 2
        params_list.append(this_repr)
        this_line_length += len(this_repr)
    lines = ''.join(params_list)
    lines = '\n'.join(l.rstrip(' ') for l in lines.split('\n'))
    return lines

def _build_repr(self):
    cls = self.__class__
    init = getattr(cls.__init__, 'deprecated_original', cls.__init__)
    init_signature = signature(init)
    if init is object.__init__:
        args = []
    else:
        args = sorted([p.name for p in init_signature.parameters.values()
                       if p.name != 'self' and p.kind != p.VAR_KEYWORD])
    class_name = self.__class__.__name__
    params = dict()
    for key in args:
        warnings.simplefilter('always', DeprecationWarning)
        try:
            with warnings.catch_warnings(record=True) as w:
                value = getattr(self, key, None)
            if len(w) and w[0].category == DeprecationWarning:
                continue
        finally:
            warnings.filters.pop(0)
        params[key] = value
    return '%s(%s)' % (class_name, _pprint(params, offset=len(class_name)))

# Simulate the classes
class _RepeatedSplits(metaclass=ABCMeta):
    def __init__(self, cv, n_repeats=10, random_state=None, **cvargs):
        if not isinstance(n_repeats, numbers.Integral):
            raise ValueError('Number of repetitions must be of Integral type.')
        if n_repeats <= 0:
            raise ValueError('Number of repetitions must be greater than 0.')
        if any(key in cvargs for key in ('random_state', 'shuffle')):
            raise ValueError('cvargs must not contain random_state or shuffle.')
        self.cv = cv
        self.n_repeats = n_repeats
        self.random_state = random_state
        self.cvargs = cvargs

    def __repr__(self):
        return _build_repr(self)

class KFold:
    pass

class StratifiedKFold:
    pass

class RepeatedKFold(_RepeatedSplits):
    def __init__(self, n_splits=5, n_repeats=10, random_state=None):
        self.n_splits = n_splits
        super().__init__(KFold, n_repeats, random_state, n_splits=n_splits)

class RepeatedStratifiedKFold(_RepeatedSplits):
    def __init__(self, n_splits=5, n_repeats=10, random_state=None):
        self.n_splits = n_splits
        super().__init__(StratifiedKFold, n_repeats, random_state, n_splits=n_splits)

# Test
r1 = repr(RepeatedKFold())
r2 = repr(RepeatedStratifiedKFold())
print('RepeatedKFold():', r1)
print('RepeatedStratifiedKFold():', r2)

assert r1 == 'RepeatedKFold(n_repeats=10, n_splits=5, random_state=None)', f'Got: {r1}'
assert r2 == 'RepeatedStratifiedKFold(n_repeats=10, n_splits=5, random_state=None)', f'Got: {r2}'

# Test with custom params
r3 = repr(RepeatedKFold(n_splits=3, n_repeats=5, random_state=42))
print('RepeatedKFold(3, 5, 42):', r3)
assert r3 == 'RepeatedKFold(n_repeats=5, n_splits=3, random_state=42)', f'Got: {r3}'

print('All tests passed!')
